/* tools/gen-sounds.mjs: copy the experimental engines over from ...Thunder Plus (dev tool, not part of the app).
 *
 *   node tools/gen-sounds.mjs /path/to/thunder-plus
 *
 * Writes (do not edit these by hand; change Thunder Plus or this script and run it again):
 *   js/engine/rendered.js    ModalCore, KeysUtil, ScannedCore (index.html), unchanged, plus their settings + presets
 *   js/engine/pump-meta.js   COIL, ORBIT, FOLD, BOING: parameter symbols in the plugin's order, ranges, presets
 *   js/engine/pump-synth.wasm  the pump plugins' sound code (pump/synth/pump-synth.wasm)
 */
import {readFileSync, writeFileSync, copyFileSync} from 'fs';
import {join, dirname} from 'path';
import {fileURLToPath} from 'url';
import vm from 'vm';

const TP = process.argv[2]; if (!TP){ console.error('usage: node tools/gen-sounds.mjs /path/to/thunder-plus'); process.exit(1); }
const OUT = join(dirname(fileURLToPath(import.meta.url)), '..', 'js', 'engine');
const html = readFileSync(join(TP, 'index.html'), 'utf8');

// the text of a balanced {...} starting at the first '{' at or after i
function block(src, i){ let d = 0, j = src.indexOf('{', i), s = j, q = null;
  for (; j < src.length; j++){ const c = src[j];
    if (q){ if (c === '\\'){ j++; continue; } if (c === q) q = null; continue; }
    if (c === '/' && src[j + 1] === '/'){ j = src.indexOf('\n', j); continue; }   // comments can hold an apostrophe
    if (c === '/' && src[j + 1] === '*'){ j = src.indexOf('*/', j) + 1; continue; }
    if (c === "'" || c === '"' || c === '`'){ q = c; continue; }
    if (c === '{') d++; else if (c === '}' && --d === 0) return src.slice(s, j + 1); }
  throw new Error('unbalanced'); }
const cls = name => { const i = html.indexOf('\nclass ' + name + ' {'); if (i < 0) throw new Error(name); return 'class ' + name + ' ' + block(html, i + 1); };

const classes = [cls('KeysUtil'), cls('SpecUtil'), cls('ModalCore'), cls('ScannedCore')];
// the settings rows and presets (Thunder Plus XUI.modal / XUI.scanned), evaluated with the label helpers stubbed
const xui = k => { const i = html.indexOf('\n  ' + k + ':{title:'); return block(html, i); };
const ctx = vm.createContext({Math, String, Number});
vm.runInContext(classes.join('\n') + `
  const nameOf = list => { const f = v => list[Math.round(v)]; f.list = list; return f; };
  const pct = v => v, hz = v => v, ms = v => v;
  globalThis.__x = {modal: ${xui('modal')}, scanned: ${xui('scanned')}};`, ctx);
const settings = {};
for (const k of ['modal', 'scanned']){
  const X = ctx.__x[k];
  settings[k] = {rows: Object.entries(X.rows).filter(([s]) => s !== 'oct').map(([s, r]) => {
      const o = {s, l: r.l, min: r.min, max: r.max, def: r.d};
      if (r.c === 'int') o.int = true; if (r.c === 'log') o.log = true; if (r.c === 'sq') o.sq = true;
      if (r.f && r.f.list) o.ch = r.f.list.slice(0, r.max - r.min + 1);
      return o; }),
    pre: X.pre.map(([n, v]) => { const c = Object.assign({}, v); delete c.oct; return [n, c]; })};
}
writeFileSync(join(OUT, 'rendered.js'), `/* js/engine/rendered.js: GENERATED by tools/gen-sounds.mjs from ...Thunder Plus index.html. Do not edit.
 * Modal (a bank of resonant modes, struck, plucked, bowed or blown) and Scanned (a ring of masses on springs, read as
 * a wave): rendered engines. Spores records each note a track uses in a Worker (render-worker.js) and plays the
 * recordings, so these never run on the audio thread. The owner's own code, unchanged. */
${classes.map(c => 'export ' + c).join('\n')}

// Settings (Thunder Plus' rows, without Octave: the track sets the pitch) and presets.
export const RENDERED = ${JSON.stringify(settings)};
`);

// pump meta: four instruments
const mctx = vm.createContext({}); vm.runInContext(readFileSync(join(TP, 'pump/synth/pump-synth-meta.js'), 'utf8').replace('globalThis.PUMP_SYNTH_META', 'globalThis.M'), mctx);
const M = mctx.M, TYPE = {coil: 2, orbit: 3, fold: 4, boing: 8};
const pump = {};
for (const k of Object.keys(TYPE)){
  const s = M.synth[k];
  pump[k] = {t: TYPE[k], name: s.name, about: s.about,
    params: s.params.map(p => { const o = {s: p.s, l: p.n, sn: p.sn, min: p.min, max: p.max, def: p.def};
      if (p.unit) o.unit = p.unit; if (p.scale === 'log') o.log = true; if (p.scale === 'pow') o.sq = true;
      if (p.flags & 2) o.int = true; if (p.ch) o.ch = p.ch; return o; }),
    pre: s.presets.map(p => [p.n, p.v])};
}
writeFileSync(join(OUT, 'pump-meta.js'), `/* js/engine/pump-meta.js: GENERATED by tools/gen-sounds.mjs from ...Thunder Plus pump/synth/pump-synth-meta.js
 * (itself generated from the pump plugins' Params.hpp). Do not edit. Parameters are in the plugin's order: the order
 * pump-synth.wasm reads them in. t = the instrument's type id in the wasm. */
export const PUMP = ${JSON.stringify(pump)};
`);
copyFileSync(join(TP, 'pump/synth/pump-synth.wasm'), join(OUT, 'pump-synth.wasm'));
console.log('ok:', Object.keys(settings).map(k => k + ' ' + settings[k].pre.length + ' presets').join(', '), '|',
  Object.keys(pump).map(k => k + ' ' + pump[k].params.length + ' params ' + pump[k].pre.length + ' presets').join(', '));
